import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/troubleshooting.md","filePath":"en/troubleshooting.md","lastUpdated":1794405696000}`),a={name:`en/troubleshooting.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><h2 id="the-order-to-check-first" tabindex="-1">The order to check first <a class="header-anchor" href="#the-order-to-check-first" aria-label="Permalink to “The order to check first”">​</a></h2><p>Checking in this order shows how far processing has got: <a href="./integration/sdk">consent and the tag</a> → <a href="./guides/sites">site settings</a> → <a href="./guides/campaigns">campaign status</a> → <a href="./guides/debugging">diagnostic panel</a>.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>What to check</th></tr></thead><tbody><tr><td>The tag is in but nothing communicates</td><td>SDK loading, consent, site ID, HTTPS, metadata sending, CSP</td></tr><tr><td>No offer appears right after opening a page</td><td>The initial decision is made, but nothing is shown if valid views, time or conditions are insufficient</td></tr><tr><td>JSON comes back but nothing is displayed</td><td>decision, campaign, display type, image loading, <code>reportShown</code> in custom code, CSP</td></tr><tr><td>It doesn&#39;t appear after being closed once</td><td><code>dismissed</code> in the browser and the display count limit</td></tr><tr><td>Settings can&#39;t be saved</td><td>Permissions, input limits, an outdated revision, the passkey re-authentication needed</td></tr><tr><td>Preview is rejected</td><td>Origin, permitted and excluded paths, campaign targets, display title, expiry</td></tr><tr><td>Another site isn&#39;t in the list</td><td>The account&#39;s site membership</td></tr></tbody></table><h2 id="you-can-t-sign-in-with-a-passkey" tabindex="-1">You can&#39;t sign in with a passkey <a class="header-anchor" href="#you-can-t-sign-in-with-a-passkey" aria-label="Permalink to “You can&#39;t sign in with a passkey”">​</a></h2><p>Check the account by email and passkey. Open it at the correct HTTPS origin, and try another registered device or key. localhost and an IP address are not the same RP.</p><p>If you lost your device, use the <a href="./guides/accounts#if-you-lose-your-device">recovery steps</a>. There is no public recovery API that registers a new administrator with only an email address.</p><h2 id="you-can-t-enter-through-access" tabindex="-1">You can&#39;t enter through Access <a class="header-anchor" href="#you-can-t-enter-through-access" aria-label="Permalink to “You can&#39;t enter through Access”">​</a></h2><p>Use an allowed email address. If the email code doesn&#39;t arrive, check what you typed, your spam folder and the expiry, and resend it yourself if needed. A JevSense invitation alone doesn&#39;t add you to what Access allows.</p><p>If you still get a 403 JSON response after entering, the operator checks that Access&#39;s audience, issuer and the fixed AUTH_ORIGIN match. Use the fixed Preview URL, not an individual Deployment URL.</p><h2 id="cloudflare-authentication-errors" tabindex="-1">Cloudflare authentication errors <a class="header-anchor" href="#cloudflare-authentication-errors" aria-label="Permalink to “Cloudflare authentication errors”">​</a></h2><p>CLOUDFLARE_API_TOKEN, each site&#39;s Jev API key and the encryption JEV_KEYRING are separate. Check the token&#39;s target account and operation permissions. A secret showing &quot;ready&quot; doesn&#39;t guarantee the real API&#39;s permission.</p><p>An account API token can&#39;t be verified with only the user-scoped <code>/user/tokens/verify</code>. Use <code>wrangler whoami</code> or the account verification API, and don&#39;t keep re-entering it just because of a 401.</p><p>For a 403 when you can&#39;t create an Access application, check the Access edit permission. For a 403 on a D1 operation, check the D1 edit permission and which database it connects to.</p><h2 id="model-or-cost-errors" tabindex="-1">Model or cost errors <a class="header-anchor" href="#model-or-cost-errors" aria-label="Permalink to “Model or cost errors”">​</a></h2><table tabindex="0"><thead><tr><th>Reason</th><th>What to do</th></tr></thead><tbody><tr><td>model_not_configured</td><td>Check the site&#39;s connection mode and API key, and the matching runtime secret</td></tr><tr><td>model_error / 502</td><td>Check the key, the model names available and the provider&#39;s status and response</td></tr><tr><td>budget_exhausted</td><td>Check the cost budget per UTC day</td></tr><tr><td>busy</td><td>Check the concurrency limit</td></tr><tr><td>rate_limited / 429</td><td>Check whether operations or requests are concentrated, and wait a while</td></tr></tbody></table><p>Preview&#39;s fixed stub can&#39;t be used to check real model failures. When you fix a key, also don&#39;t paste its value into logs or Issues.</p><h2 id="the-production-release-stops" tabindex="-1">The production release stops <a class="header-anchor" href="#the-production-release-stops" aria-label="Permalink to “The production release stops”">​</a></h2><p>Check the 40-character reviewed commit, the current HEAD, unsaved changes and the deployment record in <code>data/deployments/preview.json</code>. If there is no record, recreate Preview. Don&#39;t force a deployment to production to bypass this check.</p><h2 id="if-it-still-isn-t-resolved" tabindex="-1">If it still isn&#39;t resolved <a class="header-anchor" href="#if-it-still-isn-t-resolved" aria-label="Permalink to “If it still isn&#39;t resolved”">​</a></h2><p>Open an <a href="https://github.com/manji6/jev-personalization/issues" target="_blank" rel="noreferrer">Issue</a> with the steps to reproduce, your browser and OS, what you did, what you expected, and the error name with secrets removed. Don&#39;t share cookies, keys, tokens, form values or real browsing history.</p><h2 id="a-site-only-key-can-t-be-saved-or-isn-t-being-called" tabindex="-1">A site-only key can&#39;t be saved or isn&#39;t being called <a class="header-anchor" href="#a-site-only-key-can-t-be-saved-or-isn-t-being-called" aria-label="Permalink to “A site-only key can&#39;t be saved or isn&#39;t being called”">​</a></h2><p>If it says &quot;the encryption key is not set&quot;, the environment administrator does the <a href="./operations/jev-keys">initial setup of JEV_KEYRING</a>. If it can&#39;t be decrypted, restore the matching old-generation key or register a new API key. It does not return to a shared key automatically. Also check the display conditions, consent and the site&#39;s connection mode.</p><p>If the usage count doesn&#39;t increase, note that it doesn&#39;t increase for fixed judgments in Preview/local-review or for forced previews. A call also doesn&#39;t start when conditions are unmet or the key isn&#39;t set. &quot;Result unconfirmed&quot; includes in progress, interrupted and failed-to-save results, and you can&#39;t conclude that Jev received it or billed it. Check billing with the provider.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};